const raw = $json.text || '';

// Trim: Rauschen entfernen
const cleaned = raw
  .replace(/[ \t]+/g, ' ')       // mehrfache Leerzeichen → eines
  .replace(/\n{3,}/g, '\n\n')    // mehrfache Leerzeilen → zwei
  .replace(/·/g, '')             // dekorative Sonderzeichen
  .replace(/---.*---/g, '---')   // Trennlinien kürzen
  .trim();

const MAX_CHARS = 3000;
let text = cleaned;

if (cleaned.length > MAX_CHARS) {
  const paragraphs = cleaned.split('\n\n');
  let result = '';
  for (const p of paragraphs) {
    if ((result + p).length > MAX_CHARS) break;
    result += (result ? '\n\n' : '') + p;
  }
  text = (result || cleaned.substring(0, MAX_CHARS))
       + '\n\n[... ' + paragraphs.length + ' Absätze – Budget: ' + MAX_CHARS + ' Zeichen ...]';
}

const words           = text.split(/\s+/).filter(Boolean).length;
const estimatedTokens = Math.round(words * 1.3);
const kosten          = estimatedTokens / 1_000_000 * 2.50;

return [{ json: {
  text,
  original_chars:    raw.length,
  cleaned_chars:     cleaned.length,
  final_chars:       text.length,
  estimated_tokens:  estimatedTokens,
  kosten_usd:        '$' + kosten.toFixed(6),
  kosten_pro_1000:   '$' + (kosten * 1000).toFixed(4) + ' bei 1.000 Anfragen/Tag',
  truncated:         cleaned.length > MAX_CHARS,
  budget_used_pct:   Math.round((text.length / MAX_CHARS) * 100)
} }];

