/**
 * Improved HTML to Text Cleaner
 * Optimized for LLM processing and readability.
 */
function decodeHtmlEntities(str = '') {
  if (!str) return '';
  str = str.replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));
  str = str.replace(/&#x([0-9a-fA-F]+);/g, (_, n) => String.fromCharCode(parseInt(n, 16)));
  const entities = {
    amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
    copy: '©', reg: '®', trade: '™', bull: '•', ldquo: '"', rdquo: '"',
    ndash: '–', mdash: '—', euro: '€', pound: '£', deg: '°'
  };
  return str.replace(/&([a-zA-Z0-9]+);/g, (match, entity) => {
    return entities[entity] || match;
  });
}

function cleanHtml(html) {
  if (!html) return '';
  let text = html;
  const skipTags = ['script', 'style', 'noscript', 'svg', 'canvas', 'iframe', 'head', 'footer', 'nav', 'header', 'aside'];
  skipTags.forEach(tag => {
    const regex = new RegExp(`<${tag}[^>]*>[\\s\\S]*?<\\/${tag}>`, 'gi');
    text = text.replace(regex, '');
  });
  const blockTags = ['p', 'div', 'article', 'section', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'li', 'tr', 'blockquote'];
  blockTags.forEach(tag => {
    const openRegex = new RegExp(`<${tag}[^>]*>`, 'gi');
    const closeRegex = new RegExp(`<\\/${tag}>`, 'gi');
    text = text.replace(openRegex, '\n').replace(closeRegex, '\n');
  });
  text = text.replace(/<br\s*\/?>/gi, '\n');
  text = text.replace(/<(td|th)[^>]*>/gi, ' ');
  text = text.replace(/<[^>]+>/g, '');
  return text;
}

function normalizeWhitespace(text) {
  return text
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n/g, '\n\n')
    .trim();
}

return items.map(item => {
  const rawHtml = item.json?.data || item.json?.html;
  if (!rawHtml || typeof rawHtml !== 'string') {
    return { json: { ...item.json, data: 'Error: No valid HTML string found' } };
  }
  try {
    let output = cleanHtml(rawHtml);
    output = decodeHtmlEntities(output);
    output = normalizeWhitespace(output);

    // Token & Kosten-Schätzung
    const tokens = Math.round(output.split(/\s+/).filter(Boolean).length * 1.3);
    const kosten = tokens / 1_000_000 * 2.50;

    return {
      json: {
        ...item.json,
        cleaned_text:    output,
        beschreibung:    '✅ Mit Trim',
        chars:           output.length,
        tokens:          tokens,
        kosten_usd:      '$' + kosten.toFixed(6),
        kosten_pro_1000: '$' + (kosten * 1000).toFixed(4) + ' bei 1.000 Anfragen/Tag'
      }
    };
  } catch (error) {
    return { json: { ...item.json, error: error.message } };
  }
});
